const normalizeRun=(value:unknown):Run|null=>{if(!value||typeof value!=="object")return null;const saved=value as Partial<Run>&{quest?:unknown};if(typeof saved.name!=="string"||!Object.keys(JOBS).includes(saved.job??"")||!(["explore","battle","shop","bossChoice","relicChoice","recoveryChoice","ending"] as string[]).includes(saved.phase??"")||!Number.isInteger(saved.floor)||Number(saved.floor)<1||Number(saved.floor)>100||!Array.isArray(saved.map)||saved.map.length!==H||!saved.map.every(row=>Array.isArray(row)&&row.length===W)||!saved.player||!Number.isInteger(saved.player.x)||!Number.isInteger(saved.player.y)||!saved.equipment)return null;const floor=saved.floor??1,battle=saved.battle?{...saved.battle,catalogId:saved.battle.catalogId??monsterForBattle(saved.battle.kind??0,floor).id,intent:saved.battle.intent??"attack",turn:saved.battle.turn??0,traitUsed:saved.battle.traitUsed??false}:null,pendingEnemyTurn=saved.pendingEnemyTurn?{...saved.pendingEnemyTurn,battle:{...saved.pendingEnemyTurn.battle,catalogId:saved.pendingEnemyTurn.battle.catalogId??monsterForBattle(saved.pendingEnemyTurn.battle.kind??0,floor).id}}:null,equipment=Object.fromEntries(Object.entries(saved.equipment).map(([kind,item])=>[kind,item?normalizeOwnedGear(item):null])) as Run["equipment"],rawSupplies=saved.supplies&&typeof saved.supplies==="object"?saved.supplies:{};const supplies=Object.fromEntries(SUPPLY_IDS.map(id=>[id,Math.max(0,Math.floor(Number(rawSupplies[id])||0))]).filter(([,count])=>Number(count)>0)) as Run["supplies"];return{...(saved as Run),inventory:(saved.inventory??[]).map(normalizeOwnedGear),equipment,bombs:saved.bombs??0,supplies,combo:saved.combo??0,relics:saved.relics??[],testMode:saved.testMode??false,quest:normalizeQuestKey(saved.quest),recovery:(saved.recovery??[]).map(normalizeOwnedGear),shopPotionAvailable:saved.shopPotionAvailable??true,statuses:saved.statuses??[],pendingEnemyTurn,battle};};

