const statusFor=(b:BattleEnemy,floor:number):StatusKind=>(BOSS_TACTICS[floor]?.statusKind??monsterRecordFor(b.catalogId).statusKind??(["poison","bleed","curse","blind","paralysis"] as StatusKind[])[(b.kind+b.turn+floor)%5]) as StatusKind;
const statusDamage=(statuses:Status[])=>statuses.reduce((total,s)=>total+(s.kind==="poison"?3:s.kind==="bleed"?4:0),0);
const statusText=(statuses:Status[])=>statuses.length?` 現在：${statuses.map(s=>`${statusName[s.kind]} ${s.turns}T`).join("・")}。`:"";

function stats(run:Run){ const j=JOBS[run.job], eq=Object.values(run.equipment).filter(Boolean) as OwnedGear[], relics=run.relics??[],test=run.testMode?{hp:2000,mp:999,atk:999,def:500}:{hp:0,mp:0,atk:0,def:0}; return {maxHp:j.hp+(run.level-1)*5+eq.reduce((s,g)=>s+(g.hp||0),0)+(relics.includes("r4")?12:0)+test.hp,maxMp:j.mp+(run.level-1)*2+eq.reduce((s,g)=>s+(g.mp||0),0)+(relics.includes("r5")?5:0)+test.mp,atk:j.atk+(run.level-1)*2+eq.reduce((s,g)=>s+(g.atk||0),0)+(relics.includes("r7")?4:0)+test.atk,def:j.def+(run.level-1)+eq.reduce((s,g)=>s+(g.def||0),0)+test.def};}
const supplyUnavailableReason=(run:Run,id:SupplyId)=>{if((run.supplies[id]??0)<=0)return"持っていない";if(id==="c2"&&!run.statuses.length)return"状態異常ではない";if(id==="c7"&&run.battle?.boss)return"階層主には効かない";if(id==="c8"&&!run.statuses.some(status=>status.kind==="curse"))return"呪われていない";if(id==="c9"&&!run.statuses.some(status=>status.kind==="bleed"))return"出血していない";if(id==="c10"&&run.mp>=stats(run).maxMp)return"MPは満タン";return"";};
const passivePower=(run:Run,passive:PassiveKey)=>(Object.values(run.equipment).filter(Boolean) as OwnedGear[]).reduce((total,item)=>total+(item.passive===passive?(item.passiveValue??0):0),0);
const passiveEffect=(item:Gear)=>{if(!item.passive)return"";const value=item.passiveValue??0;return{vampire:`吸血：与えた傷の${value}%を回復`,critical:`会心率 +${value}%`,guardCounter:`防御反撃：攻撃力${value}%`,mpFlow:`攻撃命中時 MP${value}回復`,statusResist:`状態耐性 ${value}%`,lastStand:`瀕死時の傷 +${value}%`}[item.passive];};
const gearEffect=(item:Gear)=>[item.atk?`攻撃 +${item.atk}`:"",item.def?`守備 +${item.def}`:"",item.hp?`最大HP +${item.hp}`:"",item.mp?`最大MP +${item.mp}`:"",passiveEffect(item)].filter(Boolean).join("・");
const gearDelta=(item:Gear,current:OwnedGear|null|undefined)=>{const parts=([["atk","攻"],["def","守"],["hp","HP"],["mp","MP"]] as const).flatMap(([key,label])=>{const delta=(item[key]??0)-(current?.[key]??0);return delta?[`${label}${delta>0?"+":""}${delta}`]:[];});if(item.passive!==current?.passive)parts.push(item.passive?`${PASSIVE_LABELS[item.passive]}へ変更`:"特殊効果なし");return parts.join(" / ")||"能力は同等";};
const displayItem=(locale:Locale,item:Gear)=>{const master=itemById(item.id.split("-f")[0]);return master?localizedItem(locale,master):{name:item.name,effect:gearEffect(item)};};
const displayGearName=(locale:Locale,item:Gear)=>{if(locale==="ja")return item.name;const mark=item.kind==="weapon"?"⚔":item.kind==="armor"?"▣":"◉";return`${mark} ${displayItem(locale,item).name}`;};
const displayGearEffect=(locale:Locale,item:Gear)=>locale==="ja"?gearEffect(item):[item.atk?`ATK +${item.atk}`:"",item.def?`DEF +${item.def}`:"",item.hp?`Max HP +${item.hp}`:"",item.mp?`Max MP +${item.mp}`:"",item.passive?`${passiveLabel(locale,item.passive)} ${item.passiveValue??0}${item.passive==="mpFlow"?" MP":"%"}`:""].filter(Boolean).join(" · ");
